// Generated by the build from folders containing both main.js and protocol.js.
import { models } from "virtual:supported-models";
export { models };

export const modelForMidiPort = name => models.find(model => model.midiPort?.test(name?.trim() || ""));
export const modelForBleName = name => models.find(model => model.ble?.name.test(name || ""));

// Also recognize unsupported GP names so the page can explain why they are ignored.
export function modelName(name) {
  const match = /\bGP-?\s?(\d{1,3})\s?([A-Z]{0,2})\b/i.exec(name || "");
  return match ? `GP-${match[1]}${match[2]}`.toUpperCase() : null;
}
